<template><div class="auth-page"><div class="auth-glow"></div><div class="auth-card register-card"><div class="auth-brand"><span>◈</span> UAV<span>·VISION</span></div><div class="auth-kicker">CREATE YOUR WORKSPACE ID</div><h1>创建账号</h1><p>注册后即可管理个人任务与解译成果</p><el-form :model="form" @submit.prevent="submit"><el-form-item><el-input v-model="form.username" size="large" placeholder="用户名（至少 3 位）" :prefix-icon="User"/></el-form-item><el-form-item><el-input v-model="form.email" size="large" placeholder="邮箱" :prefix-icon="Message"/></el-form-item><el-form-item><el-input v-model="form.displayName" size="large" placeholder="显示名称（可选）" :prefix-icon="Postcard"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" show-password placeholder="密码（至少 6 位）" :prefix-icon="Lock"/></el-form-item><el-button class="auth-submit" size="large" type="primary" :loading="loading" @click="submit">创建个人账号</el-button></el-form><div class="auth-switch">已有账号？<el-link type="primary" @click="$router.push('/login')">返回登录</el-link></div></div></div></template>
<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{User,Lock,Message,Postcard}from'@element-plus/icons-vue';import{authApi}from'../api/http';const router=useRouter(),loading=ref(false),form=ref({username:'',email:'',displayName:'',password:''});async function submit(){if(!form.value.username||!form.value.email||!form.value.password)return ElMessage.warning('请填写用户名、邮箱和密码');loading.value=true;try{await authApi.register(form.value);ElMessage.success('注册成功');router.push('/dashboard')}catch(e){ElMessage.error(e.response?.data?.message||'注册失败')}finally{loading.value=false}}</script>
